(* ::Package:: *)

(* ::Input:: *)
(*<< NumericalCalculus`*)
(*KerrRad[a_,p_,e_,i_,\[Nu]_,\[Theta]_,\[Phi]_,M_]:={*)
(*(*First, define the orbital energy E, angular momentum L, and Carter constant Q in terms of the intrinsic binary parameters (a, e, p, i).*)*)
(*(*Below follows Appendix B of Schmidt: gr-qc/0202090 *)*)
(*(zm = (Cos[(Pi/2)-(i*(Pi/180))])^2);(*Note: This corresponds to Subscript[z, _]^2 in Schmidt*)*)
(*(ra = p/(1-e));*)
(*(rp=p/(1+e));*)
(*( \[CapitalDelta]=r^2-2r+a^2);*)
(*(*Defining coefficients to colve for orbital constants E, L, Q*)*)
(*(f=r^4+a^2*(r*(r+2)+\[CapitalDelta]*zm)); (g=2*a*r);(h=r*(r-2)+\[CapitalDelta]*(zm)/(1-zm));(d= (r^2+a^2*zm)*\[CapitalDelta]);*)
(*((d1 = d/.r->rp);(d2=d/.r->ra);(f1 =f/.r->rp);(f2=f/.r->ra);(g1= g/.r->rp);(g2 = g/.r->ra);(h1=h/.r->rp);(h2=h/.r->ra));*)
(*(k =Det[{{d1,h1},{d2,h2}}])(rho =Det[{{f1,h1},{f2,h2}}]);(sig =Det[{{g1,h1},{g2,h2}}]);(ep =Det[{{d1,g1},{d2,g2}}]);*)
(*(nu =Det[{{f1,g1},{f2,g2}}]);*)
(*(EE=En/.Solve[(rho^2+4*nu*sig)*En^4-2*(k*rho+2*ep*sig)*En^2+k^2==0,En]);*)
(*(*The roots of the above orbital energy are sorted to determine the prograde and retrograde orbital parameters.*)*)
(**)
(*(*Of the four roots: -E^(p), -E^(r), E^(p), E^(r) (where p and are refer to prograde and retrograde), E^(p)is the lower, positive energy value. Thus, Epro is assigned to the third sorted value.*)*)
(*(EE2=Sort[EE]);(Epro = EE2[[3]]);*)
(**)
(*(*The prograde angular momentum is the higher of the two values once the prograde energy is substituted into the equation. Q is computed directly.*)*)
(*(P= Lz/.Solve[(-h1)*Lz^2-(2*g1*Epro)*Lz+(f1*Epro^2)-d1==0, Lz]);(P2 = Sort[P]);(Lpro = P2[[2]]);*)
(*((Q=( (1-Epro^2)*a^2 +Lpro^2/(1-zm))*zm));*)
(*S=a;*)
